// hard real-time path
void isr_step() {
  int* p = new int(0);
  *p = 1;
  delete p;  // properly freed — the sole issue is heap use in an RT path
}

// hard real-time path
void rt_alloc() {
  void* b = std::malloc(64);
  std::free(b);
}

// interrupt handler
void on_irq() {
  int* a = new int[32];
  a[0] = 0;
  delete[] a;  // matched — sole issue is heap use in RT
}

// real-time control loop
void rt_op() {
  void* m = ::operator new(128);
  ::operator delete(m);
}

void guarded(std::mutex& m) {
  m.lock();
  if (!ready()) return;  // lock never released on this path
  m.unlock();
}

void read_cfg() {
  FILE* f = std::fopen("cfg", "r");
  if (!parse(f)) return;  // fclose skipped
  std::fclose(f);
}

void compute() {
  int* scratch = new int(0);
  may_throw();  // leaks scratch if this throws
  delete scratch;
}

void handle(int code) {
  int* buf = new int[16];
  if (code < 0) return;  // buf leaked
  process(buf);
  delete[] buf;
}

struct Buffer {
  int* data_;
  Buffer() { data_ = new int[8]; }
  ~Buffer() { delete[] data_; }
};

Widget* make_widget() {
  return new Widget();  // caller inherits a raw owning pointer
}

void load() {
  Record* r = new Record();
  r->fill();
  save(r);
  delete r;
}

void consume(Widget* w);  // does consume take ownership? unclear
void caller() {
  consume(new Widget());
}

std::vector<Task*> registry;
void enroll() {
  registry.push_back(new Task());  // who deletes these? unspecified
}

struct Node { Node* next; };
void link(Node* a, Node* b) {
  a->next = b;  // does 'a' now own 'b'? ambiguous
}

int* dangling() {
  int x = 5;
  return &x;  // address of a local — dangles at return
}

void use_after_free() {
  int* p = new int(1);
  delete p;
  *p = 2;  // dereference after lifetime ended
}

const std::string& borrow() {
  return make_name();  // binds a reference to a returned temporary
}

void invalidate(std::vector<int>& v) {
  int* p = &v[0];
  v.push_back(9);  // may reallocate, invalidating p
  *p = 3;
}

void zero(int* buf, std::size_t n) {
  for (int* p = buf; p < buf + n; ++p) {
    *p = 0;
  }
}

int nth(const int* arr, int i) {
  return *(arr + i);  // pointer arithmetic to index
}

char* tail(char* start, std::size_t len) {
  return start + len;  // computes a pointer by arithmetic
}

void advance(float*& p, int stride) {
  p += stride;  // advancing a raw pointer
}

void mixed_alloc() {
  int* p = static_cast<int*>(std::malloc(sizeof(int)));
  delete p;  // malloc'd but delete'd
}

void wrong_free() {
  int* p = new int(3);
  std::free(p);  // new'd but free'd
}

void arr_scalar() {
  Widget* w = new Widget[5];
  delete w;  // array new, scalar delete
}

void arr_scalar2() {
  int* m = new int[3]{1, 2, 3};
  delete m;  // array new, scalar delete
}

void d_arr() {
  double* d = new double[100];
  delete d;  // should be delete[]
}

void c_arr(std::size_t len) {
  char* s = new char[len];
  delete s;  // should be delete[]
}

struct P {};
void p_arr() {
  P* ps = new P[4];
  delete ps;  // should be delete[]
}

void mismatch_field(Owner* o) {
  o->items = new Item[o->n];
  delete o->items;  // should be delete[]
}

void twice() {
  int* p = new int(7);
  delete p;
  delete p;  // double free (2nd delete touches freed memory)
}

void alias_free() {
  int* p = new int(1);
  int* q = p;
  delete p;
  delete q;  // same resource freed via alias
}

void c_double(void* h) {
  void* m = std::malloc(8);
  std::free(m);
  std::free(m);  // freed twice
}

void member_double(Holder* a) {
  delete a->buf;
  reset(a);
  delete a->buf;  // buf not nulled by reset — freed again
}

void run(std::weak_ptr<Node> w) {
  w.lock()->run();  // result of lock() not null-checked before use
}

void assign(std::weak_ptr<int> w) {
  std::shared_ptr<int> s = w.lock();
  *s = 3;  // s may be null
}

void racy(std::weak_ptr<int> w) {
  if (!w.expired())
    *w.lock() = 1;  // expired()-then-lock() races; deref unchecked
}

void grab(std::weak_ptr<Session> w) {
  auto* raw = w.lock().get();
  raw->ping();  // raw may be null
}

void warn() {
  int x;  // uninitialised, unused — a different MISRA chapter
}

int area(int r) {
  return 3 * r * r;  // magic constant, not resource management
}

void narrow() {
  double d = 3.14;
  int n = d;  // implicit narrowing conversion
}

void spin() {
  int i = 0;
loop:
  if (i < 10) { ++i; goto loop; }  // control-flow rule, not Ch.22
}

void Process(int DataValue) {
  // naming-convention territory, no resource management
  (void)DataValue;
}

void ok_unique() {
  auto p = std::make_unique<int>(42);
  *p = 1;  // RAII-owned, released automatically
}

void ok_array() {
  int* a = new int[10];
  a[0] = 1;
  delete[] a;  // matched array delete
}

void ok_weak(std::weak_ptr<Node> w) {
  if (auto s = w.lock()) {
    s->run();  // locked AND null-checked
  }
}

void ok_lock(std::mutex& m) {
  std::lock_guard<std::mutex> g(m);
  work();  // RAII lock, released on any exit
}

void ok_stack() {
  std::array<int, 64> buf{};
  buf[0] = 1;  // no heap allocation at all
}
